import functions_framework
import socket
import time
import subprocess
import json

from google.cloud import secretmanager


def get_secret(project_id: str, secret_id: str) -> str:
    client = secretmanager.SecretManagerServiceClient()
    name = f"projects/{project_id}/secrets/{secret_id}/versions/latest"
    response = client.access_secret_version(request={"name": name})
    return response.payload.data.decode("UTF-8")


def validate_tcp(ip: str, port: int, timeout: int = 10) -> dict:
    start = time.time()
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        sock.connect((ip, port))
        sock.close()
        elapsed = int((time.time() - start) * 1000)
        return {"success": True, "response_time_ms": elapsed, "details": f"TCP port {port} open"}
    except Exception as e:
        elapsed = int((time.time() - start) * 1000)
        return {"success": False, "response_time_ms": elapsed, "details": str(e)}


def validate_postgresql(ip: str, port: int, project_id: str, vm_name: str) -> dict:
    start = time.time()
    try:
        creds = json.loads(get_secret(project_id, f"restore-test-{vm_name}-credentials"))
        user = creds.get("user", "postgres")
        password = creds.get("password", "")
        dbname = creds.get("database", "postgres")

        import psycopg2
        conn = psycopg2.connect(
            host=ip, port=port, user=user, password=password,
            dbname=dbname, connect_timeout=15
        )
        cur = conn.cursor()
        cur.execute("SELECT 1")
        result = cur.fetchone()
        cur.close()
        conn.close()

        elapsed = int((time.time() - start) * 1000)
        return {
            "success": result[0] == 1,
            "response_time_ms": elapsed,
            "details": "SELECT 1 -> OK",
        }
    except Exception as e:
        elapsed = int((time.time() - start) * 1000)
        return {"success": False, "response_time_ms": elapsed, "details": str(e)}


def validate_mongodb(ip: str, port: int, project_id: str, vm_name: str) -> dict:
    start = time.time()
    try:
        creds = json.loads(get_secret(project_id, f"restore-test-{vm_name}-credentials"))
        user = creds.get("user", "")
        password = creds.get("password", "")

        from pymongo import MongoClient
        if user and password:
            uri = f"mongodb://{user}:{password}@{ip}:{port}/?authSource=admin"
        else:
            uri = f"mongodb://{ip}:{port}/"

        client = MongoClient(uri, serverSelectionTimeoutMS=15000)
        result = client.admin.command("ping")
        client.close()

        elapsed = int((time.time() - start) * 1000)
        return {
            "success": result.get("ok") == 1.0,
            "response_time_ms": elapsed,
            "details": "ping -> OK",
        }
    except Exception as e:
        elapsed = int((time.time() - start) * 1000)
        return {"success": False, "response_time_ms": elapsed, "details": str(e)}


def validate_redis(ip: str, port: int, project_id: str, vm_name: str) -> dict:
    start = time.time()
    try:
        import redis as r
        creds_raw = None
        try:
            creds_raw = get_secret(project_id, f"restore-test-{vm_name}-credentials")
        except Exception:
            pass

        password = None
        if creds_raw:
            try:
                creds = json.loads(creds_raw)
                password = creds.get("password")
            except json.JSONDecodeError:
                password = creds_raw.strip()

        client = r.Redis(host=ip, port=port, password=password, socket_timeout=15)
        pong = client.ping()
        client.close()

        elapsed = int((time.time() - start) * 1000)
        return {
            "success": pong is True,
            "response_time_ms": elapsed,
            "details": "PING -> PONG",
        }
    except Exception as e:
        elapsed = int((time.time() - start) * 1000)
        return {"success": False, "response_time_ms": elapsed, "details": str(e)}


def validate_rabbitmq(ip: str, port: int, project_id: str, vm_name: str) -> dict:
    """Validate RabbitMQ by checking TCP connectivity to management port."""
    return validate_tcp(ip, port, timeout=15)


def validate_web(ip: str, port: int) -> dict:
    start = time.time()
    try:
        import requests
        resp = requests.get(f"http://{ip}:{port}/", timeout=15, allow_redirects=True)

        elapsed = int((time.time() - start) * 1000)
        return {
            "success": resp.status_code < 500,
            "response_time_ms": elapsed,
            "details": f"HTTP {resp.status_code}",
        }
    except Exception as e:
        elapsed = int((time.time() - start) * 1000)
        return {"success": False, "response_time_ms": elapsed, "details": str(e)}


def validate_windows(ip: str, port: int) -> dict:
    return validate_tcp(ip, port, timeout=30)


VALIDATORS = {
    "postgresql": validate_postgresql,
    "mongodb": validate_mongodb,
    "redis": validate_redis,
    "rabbitmq": validate_rabbitmq,
    "web": validate_web,
    "windows": validate_windows,
}


@functions_framework.http
def validate_vm(request):
    from flask import jsonify

    body = request.get_json(silent=True) or {}

    vm_name = body.get("vm_name", "")
    vm_ip = body.get("vm_ip", "")
    project_id = body.get("project_id", "")
    app_type = body.get("app_type", "web")
    validation_port = body.get("validation_port", 80)

    if not vm_ip:
        return jsonify({"success": False, "response_time_ms": 0, "details": "No VM IP provided"}), 400

    validator = VALIDATORS.get(app_type)
    if not validator:
        return jsonify({"success": False, "response_time_ms": 0, "details": f"Unknown app_type: {app_type}"}), 400

    # Validators that need credentials take extra params
    if app_type in ("postgresql", "mongodb", "redis", "rabbitmq"):
        result = validator(vm_ip, validation_port, project_id, vm_name)
    else:
        result = validator(vm_ip, validation_port)

    return jsonify(result), 200

