#-----------------------------------------
# Cloud Scheduler job to trigger the workflow
#-----------------------------------------
locals {
  workflow_args = {
    project_id    = local.project_id[terraform.workspace]
    environment   = terraform.workspace
    vms           = local.vms[terraform.workspace]
    bucket        = module.evidence_bucket.bucket_name
    validator_url = google_cloudfunctions2_function.vm_validator.service_config[0].uri
    network       = local.network
    subnet        = local.subnet_ids[local.subnet_name]
  }
}

resource "google_cloud_scheduler_job" "restore_test" {
  name        = "restore-test-trigger"
  description = "Triggers automated restore test workflow"
  project     = local.project_id[terraform.workspace]
  region      = local.region.principal
  schedule    = local.scheduler_cron[terraform.workspace]
  time_zone   = "America/Bogota"

  http_target {
    http_method = "POST"
    uri         = "https://workflowexecutions.googleapis.com/v1/${google_workflows_workflow.restore_test.id}/executions"
    headers = {
      "Content-Type" = "application/json"
    }
    body = base64encode(jsonencode({
      argument = jsonencode(local.workflow_args)
    }))

    oauth_token {
      service_account_email = module.sa-permissions.service_account_email
      scope                 = "https://www.googleapis.com/auth/cloud-platform"
    }
  }
}

